'use strict';

var log = require('loglevel');

function createLoggerMiddleware(options) {
  return async ({
    request,
    next,
    context
  }) => {
    const isTorusInternal = context.get("isTorusInternal");
    try {
      const result = await next();
      if (!isTorusInternal) {
        log.info(`RPC (${options.origin}):`, request, "->", result);
      }
      return result;
    } catch (error) {
      log.warn("Error in RPC response:\n", error);
      if (!isTorusInternal) {
        log.info(`RPC (${options.origin}):`, request, "->", error);
      }
      throw error;
    }
  };
}

exports.createLoggerMiddleware = createLoggerMiddleware;
